'use strict';

// MODULES //

var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var isCollection = require( '@stdlib/assert/is-collection' );
var isIntegerArray = require( '@stdlib/assert/is-integer-array' ).primitives;
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var normalizeIndices = require( '@stdlib/ndarray/base/to-unique-normalized-indices' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Validates function options.
*
* @private
* @param {Object} opts - destination object
* @param {NonNegativeInteger} ndims - number of input ndarray dimensions
* @param {Options} options - function options
* @param {string} [options.prefix] - prefix to prepend to each joined string
* @param {string} [options.suffix] - suffix to append to each joined string
* @param {ArrayLikeObject} [options.separators] - separators
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {boolean} [options.keepdims] - boolean indicating whether the reduced dimensions should be included in the returned ndarray as singleton dimensions
* @returns {(Error|null)} null or an error object
*
* @example
* var opts = {
*     'prefix': '',
*     'suffix': '',
*     'separators': [ ',' ],
*     'dims': [ 0, 1 ],
*     'keepdims': false
* };
* var options = {
*     'separators': [ ' + ', ' = ' ],
*     'dims': [ -1 ]
* };
* var err = validate( opts, 2, options );
* if ( err ) {
*     throw err;
* }
*/
function validate( opts, ndims, options ) {
	if ( !isPlainObject( options ) ) {
		return new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasOwnProp( options, 'prefix' ) ) {
		opts.prefix = options.prefix;
	}
	if ( hasOwnProp( options, 'suffix' ) ) {
		opts.suffix = options.suffix;
	}
	if ( hasOwnProp( options, 'separators' ) ) {
		opts.separators = options.separators;
		if ( !isCollection( opts.separators ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array-like object. Option: `%s`.', 'separators', opts.separators ) );
		}
	}
	if ( hasOwnProp( options, 'dims' ) ) {
		if ( !isIntegerArray( options.dims ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be an array of integers. Option: `%s`.', 'dims', options.dims ) );
		}
		opts.dims = normalizeIndices( options.dims, ndims-1 );
		if ( opts.dims === null ) {
			return new RangeError( format( 'invalid option. `%s` option contains an out-of-bounds dimension index.', 'dims' ) );
		}
		if ( opts.dims.length !== options.dims.length ) {
			return new Error( format( 'invalid option. `%s` option contains duplicate indices.', 'dims' ) );
		}
	}
	if ( hasOwnProp( options, 'keepdims' ) ) {
		opts.keepdims = options.keepdims;
		if ( !isBoolean( opts.keepdims ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'keepdims', opts.keepdims ) );
		}
	}
	return null;
}


// EXPORTS //

module.exports = validate;
